import{_ as t,o as e,c as s,a0 as o}from"./chunks/framework.BpJS36ta.js";const u=JSON.parse('{"title":"Crypto Module","description":"","frontmatter":{},"headers":[],"relativePath":"modules/syntax/crypto.md","filePath":"modules/syntax/crypto.md"}'),r={name:"modules/syntax/crypto.md"};function n(d,a,i,c,p,h){return e(),s("div",null,[...a[0]||(a[0]=[o('<h1 id="crypto-module" tabindex="-1">Crypto Module <a class="header-anchor" href="#crypto-module" aria-label="Permalink to &quot;Crypto Module&quot;">​</a></h1><p>Module <code>crypto</code> menyediakan fungsi hashing dan encoding berbasis OpenSSL.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import crypto from rupa</span></span></code></pre></div><h2 id="fungsi" tabindex="-1">Fungsi <a class="header-anchor" href="#fungsi" aria-label="Permalink to &quot;Fungsi&quot;">​</a></h2><h3 id="crypto-md5-str" tabindex="-1">crypto.md5(str) <a class="header-anchor" href="#crypto-md5-str" aria-label="Permalink to &quot;crypto.md5(str)&quot;">​</a></h3><p>Hash string menggunakan MD5 (128-bit). Hanya untuk checksum, bukan keamanan.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(crypto.md5(&quot;hello&quot;))</span></span></code></pre></div><h3 id="crypto-sha1-str" tabindex="-1">crypto.sha1(str) <a class="header-anchor" href="#crypto-sha1-str" aria-label="Permalink to &quot;crypto.sha1(str)&quot;">​</a></h3><p>Hash string menggunakan SHA-1 (160-bit).</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(crypto.sha1(&quot;hello&quot;))</span></span></code></pre></div><h3 id="crypto-sha256-str" tabindex="-1">crypto.sha256(str) <a class="header-anchor" href="#crypto-sha256-str" aria-label="Permalink to &quot;crypto.sha256(str)&quot;">​</a></h3><p>Hash string menggunakan SHA-256 (256-bit).</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(crypto.sha256(&quot;hello&quot;))</span></span></code></pre></div><h3 id="crypto-sha512-str" tabindex="-1">crypto.sha512(str) <a class="header-anchor" href="#crypto-sha512-str" aria-label="Permalink to &quot;crypto.sha512(str)&quot;">​</a></h3><p>Hash string menggunakan SHA-512 (512-bit).</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(crypto.sha512(&quot;hello&quot;))</span></span></code></pre></div><h3 id="crypto-hmac-key-message" tabindex="-1">crypto.hmac(key, message) <a class="header-anchor" href="#crypto-hmac-key-message" aria-label="Permalink to &quot;crypto.hmac(key, message)&quot;">​</a></h3><p>HMAC-SHA256: message authentication code dari <code>message</code> dengan <code>key</code>.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(crypto.hmac(&quot;secret-key&quot;, &quot;hello&quot;))</span></span></code></pre></div><h3 id="crypto-base64encode-str" tabindex="-1">crypto.base64Encode(str) <a class="header-anchor" href="#crypto-base64encode-str" aria-label="Permalink to &quot;crypto.base64Encode(str)&quot;">​</a></h3><p>Encode string ke Base64.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(crypto.base64Encode(&quot;Hello Rupa!&quot;))</span></span></code></pre></div><h3 id="crypto-base64decode-str" tabindex="-1">crypto.base64Decode(str) <a class="header-anchor" href="#crypto-base64decode-str" aria-label="Permalink to &quot;crypto.base64Decode(str)&quot;">​</a></h3><p>Decode Base64 ke string.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(crypto.base64Decode(crypto.base64Encode(&quot;Hello Rupa!&quot;)))</span></span></code></pre></div><h2 id="ringkasan" tabindex="-1">Ringkasan <a class="header-anchor" href="#ringkasan" aria-label="Permalink to &quot;Ringkasan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fungsi</th><th>Parameter</th><th>Return</th></tr></thead><tbody><tr><td><code>md5(str)</code></td><td>string</td><td>string hex</td></tr><tr><td><code>sha1(str)</code></td><td>string</td><td>string hex</td></tr><tr><td><code>sha256(str)</code></td><td>string</td><td>string hex</td></tr><tr><td><code>sha512(str)</code></td><td>string</td><td>string hex</td></tr><tr><td><code>hmac(key, message)</code></td><td>dua string</td><td>string hex</td></tr><tr><td><code>base64Encode(str)</code></td><td>string</td><td>string</td></tr><tr><td><code>base64Decode(str)</code></td><td>string</td><td>string</td></tr></tbody></table><h2 id="catatan" tabindex="-1">Catatan <a class="header-anchor" href="#catatan" aria-label="Permalink to &quot;Catatan&quot;">​</a></h2><ul><li>Semua hash mengembalikan string hex lowercase.</li><li><code>md5</code>/<code>sha1</code> hanya untuk checksum kompatibilitas — untuk kebutuhan baru gunakan <code>sha256</code>/<code>sha512</code>.</li><li><code>hmac</code> memakai SHA-256.</li></ul>',29)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
